/**
 * PH EVO STUDIO — GEMINI ANALYZER (SMFF PHASE A)
 * ═══════════════════════════════════════════════════════════════
 * Ingests the entire repository context to identify profitable feature gaps.
 */
export class GeminiAnalyzer {
  constructor(apiKey) {
    this.apiKey = apiKey;
    this.model = "gemini-1.5-pro"; // Large context model
  }
  async analyzeProject(rootPath) {
    console.log(`🔍 [GeminiAnalyzer] Ingesting project context from: ${rootPath}`);
    const context = this.harvestCodebase(rootPath);
    const prompt = `
      You are the PromptHouse Evo Studio "Product Architect."
      I am providing the entire source code of the studio below.
      YOUR GOAL: 
      Identify 3 distinct, high-value features that are currently MISSING from this studio.
      These features must be something users would pay for (micro-SaaS).
      Output your response as a JSON array of "missions":
      [
        {
          "id": "feature_id",
          "name": "Feature Name",
          "description": "What it does and why it's valuable.",
          "estimatedPrice": 900, // price in cents
          "complexity": "HIGH|MEDIUM|LOW",
          "techStack": ["React", "Vite", "Stripe"]
        }
      ]
      PROJECT CONTEXT:
      ${context}
    `;
    return await this.callGemini(prompt);
  }
  harvestCodebase(dir, depth = 0) {
    if (depth > 5) return ""; // Limit depth
    let context = "";
    const files = readdirSync(dir);
    for (const file of files) {
      if (file === 'node_modules' || file === '.git' || file === 'dist' || file === '.prompthouse-data') continue;
      const fullPath = join(dir, file);
      const stats = statSync(fullPath);
      if (stats.isDirectory()) {
        context += `\n--- DIRECTORY: ${file} ---\n`;
        context += this.harvestCodebase(fullPath, depth + 1);
      } else if (file.endsWith('.js') || file.endsWith('.jsx') || file.endsWith('.css')) {
        const content = readFileSync(fullPath, 'utf8');
        context += `\nFILE: ${file}\nCONTENT:\n${content.substring(0, 2000)}\n`; // Sample first 2k chars per file
      }
    }
    return context;
  }
  async callGemini(prompt) {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${this.model}:generateContent?key=${this.apiKey}`;
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { response_mime_type: "application/json" }
        })
      });
      const data = await response.json();
      if (data.error) throw new Error(data.error.message);
      const text = data.candidates[0].content.parts[0].text;
      return JSON.parse(text);
    } catch (e) {
      console.error('❌ [GeminiAnalyzer] Error:', e.message);
      return { error: e.message };
    }
  }
}

import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from 'fs';
import { join } from 'path';
import crypto from 'crypto';
/**
 * Local Cache for AI Responses — v2 (Performance Edition)
 * Hybrid in-memory + disk cache with TTL and LRU eviction.
 * Cache hits are instant (no disk I/O). Disk is write-through for persistence.
 */
export class LocalCache {
  constructor(cacheDir = '.prompthouse-data/cache', options = {}) {
    this.cacheDir = join(process.cwd(), cacheDir);
    this.memoryCache = new Map();
    this.maxMemoryEntries = options.maxMemoryEntries || 200;
    this.ttlMs = options.ttlMs || 1000 * 60 * 60; // 1 hour default TTL
    if (!existsSync(this.cacheDir)) {
      mkdirSync(this.cacheDir, { recursive: true });
    }
    // Pre-warm memory cache from disk on startup
    this._warmFromDisk();
  }
  _warmFromDisk() {
    try {
      const files = readdirSync(this.cacheDir).filter(f => f.endsWith('.json'));
      // Only warm the most recent entries
      const toWarm = files.slice(-this.maxMemoryEntries);
      for (const file of toWarm) {
        try {
          const data = JSON.parse(readFileSync(join(this.cacheDir, file), 'utf8'));
          const hash = file.replace('.json', '');
          this.memoryCache.set(hash, { data, ts: Date.now() });
        } catch { /* skip corrupt entries */ }
      }
      console.error(`[CACHE] Pre-warmed ${this.memoryCache.size} entries from disk`);
    } catch { /* no cache dir yet */ }
  }
  getHash(messages, options = {}) {
    const data = JSON.stringify({ messages, options });
    return crypto.createHash('md5').update(data).digest('hex');
  }
  get(messages, options = {}) {
    const hash = this.getHash(messages, options);
    // Check memory first (instant)
    const memEntry = this.memoryCache.get(hash);
    if (memEntry) {
      if (Date.now() - memEntry.ts < this.ttlMs) {
        return memEntry.data;
      }
      // TTL expired — evict
      this.memoryCache.delete(hash);
    }
    // Fall back to disk
    const filePath = join(this.cacheDir, `${hash}.json`);
    if (existsSync(filePath)) {
      try {
        const data = JSON.parse(readFileSync(filePath, 'utf8'));
        // Promote to memory
        this.memoryCache.set(hash, { data, ts: Date.now() });
        this._evictIfNeeded();
        return data;
      } catch {
        return null;
      }
    }
    return null;
  }
  set(messages, options = {}, response) {
    const hash = this.getHash(messages, options);
    // Write to memory (instant)
    this.memoryCache.set(hash, { data: response, ts: Date.now() });
    this._evictIfNeeded();
    // Write-through to disk (async-safe, fire and forget)
    const filePath = join(this.cacheDir, `${hash}.json`);
    try {
      writeFileSync(filePath, JSON.stringify(response), 'utf8');
    } catch { /* disk write failed, memory cache still valid */ }
    return true;
  }
  _evictIfNeeded() {
    if (this.memoryCache.size > this.maxMemoryEntries) {
      // Evict oldest entry (LRU)
      const oldest = this.memoryCache.keys().next().value;
      this.memoryCache.delete(oldest);
    }
  }
}

import fetch from 'node-fetch';
/**
 * Prompt Compressor
 * Uses the local Evo LLM (Ollama) to compress prompt context.
 * Saves API costs by reducing token count.
 */
export class PromptCompressor {
  constructor(ollamaUrl = 'http://localhost:11434') {
    this.ollamaUrl = ollamaUrl;
    this.model = 'llama3'; // Fallback to standard model if 'evo-lm' is not found
  }
  async compress(text) {
    console.log(`[COMPRESSOR] Attempting to compress ${text.length} chars...`);
    try {
      const response = await fetch(`${this.ollamaUrl}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: this.model,
          messages: [
            { 
              role: 'system', 
              content: 'You are a prompt compression engine. Summarize the following technical context into a dense, high-density summary. Keep all file paths, function names, and critical logic. Remove all fluff, explanations, and filler words. Output ONLY the compressed context.' 
            },
            { role: 'user', content: text }
          ],
          stream: false
        }),
        signal: AbortSignal.timeout(30000) // 30s timeout
      });
      if (!response.ok) {
        throw new Error(`Ollama error: ${response.statusText}`);
      }
      const data = await response.json();
      const compressed = data.message?.content || data.response || '';
      console.log(`[COMPRESSOR] Compressed from ${text.length} to ${compressed.length} chars.`);
      return compressed;
    } catch (e) {
      console.error(`[COMPRESSOR] Failed to compress:`, e.message);
      // Fallback: Return original text if compression fails
      return text;
    }
  }
}

